// frontend/packages/project-protocol/src/app-path.ts
function isAppPath(path) {
  if (!path.startsWith("/") || path.startsWith("//") || path.includes("\\") || hasControlCharacter(path))
    return false;
  try {
    return (path.split(/[?#]/, 1)[0] ?? "").split("/").every((segment) => {
      const decoded = decodeURIComponent(segment);
      return decoded !== "." && decoded !== ".." && !decoded.includes("/") && !decoded.includes("\\") && !hasControlCharacter(decoded);
    });
  } catch {
    return false;
  }
}
function hasControlCharacter(value) {
  return Array.from(value).some((char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127);
}

