// frontend/packages/project-protocol/src/network.ts
var HOST_LABEL = "[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?";
var HOST_PATTERN = new RegExp(`^(?:\\*\\.)?(?:${HOST_LABEL}\\.)+[a-z]{2,63}$`);
var WILDCARD_PATTERN = new RegExp(`^\\*\\.${HOST_LABEL}\\.(?:${HOST_LABEL}\\.)*[a-z]{2,63}$`);
var INTERNAL_SUFFIXES = [
  ".localhost",
  ".local",
  ".internal",
  ".lan",
  ".home.arpa",
  ".intranet"
];
var PLATFORM_HOST_SUFFIXES = [
  "supabase.co",
  "supabase.in",
  "turso.io",
  "r2.cloudflarestorage.com",
  "r2.dev"
];
function normalizeHost(host) {
  return host.toLowerCase().replace(/\.$/, "");
}
function isIpLiteral(host) {
  return host.startsWith("[") || /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host);
}
function hasSuffix(host, suffix) {
  return host === suffix || host.endsWith(`.${suffix}`);
}
function isInternal(host) {
  return host === "localhost" || !host.includes(".") || INTERNAL_SUFFIXES.some((suffix) => host.endsWith(suffix));
}
function isPlatformHost(host) {
  return PLATFORM_HOST_SUFFIXES.some((suffix) => hasSuffix(host, suffix));
}
function matchesEgressHost(host, pattern) {
  const target = normalizeHost(host);
  if (pattern.startsWith("*."))
    return target.endsWith(pattern.slice(1)) && target !== pattern.slice(2);
  return target === pattern;
}
function hostIssue(host) {
  if (isIpLiteral(host))
    return "ip_literal";
  const bare = host.startsWith("*.") ? host.slice(2) : host;
  if (isInternal(bare))
    return "internal_host";
  if (isPlatformHost(bare))
    return "platform_host";
  return null;
}
function egressDeclarationIssue(declaration) {
  if (isIpLiteral(declaration))
    return "ip_literal";
  if (!HOST_PATTERN.test(declaration))
    return "invalid_host";
  if (declaration.startsWith("*.") && !WILDCARD_PATTERN.test(declaration))
    return "invalid_host";
  return hostIssue(declaration);
}
function browserOriginIssue(declaration) {
  if (!declaration.startsWith("https://"))
    return "invalid_origin";
  const host = declaration.slice("https://".length);
  if (isIpLiteral(host))
    return "ip_literal";
  if (!HOST_PATTERN.test(host))
    return "invalid_origin";
  if (host.startsWith("*.") && !WILDCARD_PATTERN.test(host))
    return "invalid_origin";
  return hostIssue(host);
}
function isGateway(url2, gatewayUrl) {
  if (!gatewayUrl)
    return false;
  const gateway = new URL(gatewayUrl);
  const base = gateway.pathname.endsWith("/") ? gateway.pathname : `${gateway.pathname}/`;
  return url2.origin === gateway.origin && (url2.pathname === gateway.pathname || url2.pathname.startsWith(base));
}
function checkEgress(input, policy) {
  let url2;
  try {
    url2 = new URL(input);
  } catch {
    return { allowed: false, reason: "invalid_url" };
  }
  const host = normalizeHost(url2.hostname);
  if (isGateway(url2, policy.gatewayUrl))
    return { allowed: true, host };
  if (url2.protocol !== "https:")
    return { allowed: false, reason: "not_https", host };
  if (url2.username !== "" || url2.password !== "")
    return { allowed: false, reason: "credentials", host };
  if (url2.port !== "")
    return { allowed: false, reason: "port", host };
  if (isIpLiteral(host))
    return { allowed: false, reason: "ip_literal", host };
  if (isInternal(host))
    return { allowed: false, reason: "internal_host", host };
  if (isPlatformHost(host))
    return { allowed: false, reason: "platform_host", host };
  if (!policy.egress.some((pattern) => matchesEgressHost(host, pattern))) {
    return { allowed: false, reason: "not_declared", host };
  }
  return { allowed: true, host };
}

