// frontend/packages/project-gateway/src/erase/erase.ts
var ERASE_FILE_BATCH = 100;
async function eraseProjectUser(db, input, removeObject) {
  const userIds = await findErasableUsers(db, {
    globalUserId: input.globalUserId ?? "",
    projectUserIds: input.projectUserIds
  });
  if (userIds.length === 0)
    return { status: "absent", users: 0, files: 0 };
  const files = await listOwnedFiles(db, userIds, ERASE_FILE_BATCH + 1);
  const batch = files.slice(0, ERASE_FILE_BATCH);
  for (const file2 of batch) {
    if (file2.status !== "deleted")
      await removeObject(file2);
  }
  if (batch.length > 0) {
    await deleteFiles(db, batch.map((file2) => file2.id));
  }
  if (files.length > ERASE_FILE_BATCH) {
    return { status: "continue", users: userIds.length, files: batch.length };
  }
  try {
    await eraseUsers(db, userIds, {
      requestId: input.requestId,
      at: input.at,
      schema: input.schema
    });
  } catch (cause) {
    if (isForeignKeyViolation(cause)) {
      throw new GatewayError("CONFLICT", "a relation restricts deleting the user", { cause });
    }
    throw cause;
  }
  return { status: "erased", users: userIds.length, files: batch.length };
}
