      if (chunk.model)
        completion.model = chunk.model;
      if (chunk.created)
        completion.created = chunk.created;
      if (chunk.usage)
        completion.usage = chunk.usage;
      if (chunk.error)
        completion.refused = chunk.error.message ?? "provider error";
