// frontend/packages/project-gateway/src/internal/workspaces.ts
async function createWorkspace(db, input) {
  const id = crypto.randomUUID();
  const at = input.now.toISOString();
  await db.batch([
    {
      sql: `INSERT INTO "Workspace" ("id", "name", "createdAt") VALUES (?, ?, ?)`,
      args: [id, input.name, at]
    },
    {
      sql: `INSERT INTO "Membership" ("workspaceId", "userId", "role", "createdAt") VALUES (?, ?, 'owner', ?)`,
      args: [id, input.userId, at]
    },
    audit(input, input.userId, "workspace.create", `Workspace:${id}`)
  ], "write");
  return { id, name: input.name };
}
async function workspaceRoleOf2(db, workspaceId, userId) {
  const result = await db.execute({
    sql: `SELECT "role" FROM "Membership" WHERE "workspaceId" = ? AND "userId" = ?`,
    args: [workspaceId, userId]
  });
  const row = result.rows[0];
  return row ? String(row.role) : null;
}
async function workspaceNames(db, workspaceIds) {
  const result = await db.execute({
    sql: `SELECT "id", "name" FROM "Workspace" WHERE "id" IN (SELECT value FROM json_each(?))`,
    args: [JSON.stringify([...new Set(workspaceIds)])]
  });
  return new Map(result.rows.map((row) => [String(row.id), String(row.name)]));
}
async function projectUserIdsByGlobal(db, globalUserIds) {
  const result = await db.execute({
    sql: `SELECT "id", "globalUserId" FROM "User" WHERE "globalUserId" IN (SELECT value FROM json_each(?))`,
    args: [JSON.stringify([...new Set(globalUserIds)])]
  });
  return new Map(result.rows.map((row) => [String(row.globalUserId), String(row.id)]));
}
async function joinWorkspace(db, input) {
  const at = input.now.toISOString();
  const results = await db.batch([
    {
      sql: `INSERT INTO "Membership" ("workspaceId", "userId", "role", "createdAt")
              SELECT w."id", ?, ?, ? FROM "Workspace" w WHERE w."id" = ?
              AND NOT EXISTS (SELECT 1 FROM "AuditEvent" WHERE "id" = ?)
              ON CONFLICT ("workspaceId", "userId") DO NOTHING`,
      args: [input.userId, input.role, at, input.workspaceId, input.invitationId]
    },
    audit(input, input.userId, "workspace.join", `Workspace:${input.workspaceId}`, true, input.invitationId),
    {
      sql: `SELECT "role" FROM "Membership" WHERE "workspaceId" = ? AND "userId" = ?`,
      args: [input.workspaceId, input.userId]
    }
  ], "write");
  const row = results.at(-1)?.rows[0];
  return row ? String(row.role) : null;
}
function audit(context, actorId, action2, resource, onlyIfWorkspaceExists = false, eventId = crypto.randomUUID()) {
  const workspaceId = resource.slice(resource.indexOf(":") + 1);
  return {
    sql: `INSERT INTO "AuditEvent" ("id", "at", "requestId", "appSlug", "actorId", "action", "resource", "decision")
          SELECT ?, ?, ?, ?, ?, ?, ?, 'allow'
          WHERE ? = 0 OR EXISTS (SELECT 1 FROM "Workspace" WHERE "id" = ?)
          ON CONFLICT ("id") DO NOTHING`,
    args: [
      eventId,
      context.now.toISOString(),
      context.requestId,
      context.appSlug,
      actorId,
      action2,
      resource,
      onlyIfWorkspaceExists ? 1 : 0,
      workspaceId
    ]
  };
}

// frontend/packages/project-gateway/src/workspaces/routes.ts
var WORKSPACE_COST = 1;
