// frontend/packages/project-gateway/src/gateway.ts
function createGateway(adapters, config3, logger = consoleLogger, realtimeTransport) {
  const app = createBaseApp(config3, logger, (origin2) => adapters.registry.liveOriginAllowed(origin2));
  const runtime = createDbRuntime(adapters);
  const realtime2 = createRealtimeService(adapters, config3, runtime);
  if (realtimeTransport)
    app.use("/v1/*", async (c2, next) => {
      try {
        await next();
      } finally {
        if (["POST", "PUT", "PATCH", "DELETE"].includes(c2.req.method) && ["/v1/db/", "/v1/storage/", "/v1/workspaces/", "/v1/safety/"].some((path) => c2.req.path.startsWith(path)) && c2.get("realtimeWakeScope")) {
          try {
            await realtimeTransport.wake(c2.get("realtimeWakeScope"));
          } catch (error51) {
            logger.log("warn", "Realtime wake deferred", {
              code: error51 instanceof GatewayError ? error51.code : "GATEWAY_UNAVAILABLE",
              request_id: c2.get("requestId")
            });
          }
        }
      }
    });
  app.get("/v1/.well-known/jwks.json", async (c2) => {
    c2.header("Cache-Control", "public, max-age=300");
    return c2.json(await adapters.signer.publicJwks());
  });
  registerSessionInitializationRoute(app, adapters, logger);
  registerTokenRoutes(app, adapters, config3);
  registerAiRoutes(app, adapters, config3, runtime, logger);
  registerAiOpenAiRoutes(app, adapters, config3, runtime, logger);
  registerDeliveryRoutes(app, adapters, config3);
  registerDirectAuthRoutes(app, adapters, config3);
  registerProfileRoutes(app, adapters, config3);
  registerConnectionRoutes(app, adapters, config3);
  registerApiAuthorizationRoutes(app, adapters, config3);
  registerPythonRoutes(app, adapters, config3);
  registerPythonDevRoutes(app, adapters, config3);
  app.post("/v1/realtime/tickets", async (c2) => {
    if (!realtimeTransport)
      throw new GatewayError("REALTIME_DISABLED", "Realtime transport is not configured");
    const origin2 = c2.req.header("origin");
    if (!origin2)
      throw new GatewayError("FORBIDDEN", "Realtime requires an origin");
    const raw2 = await readBody(c2);
    if (new TextEncoder().encode(raw2).byteLength > REALTIME_LIMITS.frameBytes)
      throw new GatewayError("PAYLOAD_TOO_LARGE", "Realtime subscription too large");
    let input;
    try {
      input = JSON.parse(raw2);
    } catch (cause) {
      throw new GatewayError("VALIDATION_FAILED", "invalid Realtime subscription", { cause });
    }
    const session2 = await realtime2.prepare(bearerOf(c2), origin2, input);
    c2.header("Access-Control-Allow-Origin", origin2);
    c2.header("Vary", "Origin", { append: true });
    return c2.json(await realtimeTransport.issue(session2));
  });
  registerDbRoutes(app, adapters, config3, logger, runtime);
  registerStorageRoutes(app, adapters, config3, runtime);
  registerSafetyRoutes(app, adapters, config3);
  registerNotificationRoutes(app, adapters, config3);
  registerServerNotificationRoutes(app, adapters);
  registerJobRoutes(app, adapters);
  if (config3.erase)
    registerEraseRoutes(app, adapters, config3.erase);
  registerWorkspaceRoutes(app, adapters, config3);
  return Object.assign(app, { realtime: realtime2 });
}
